-- Terminal palette for the rex colorscheme: asks the terminal for its colors (OSC 4/10/11) and
-- caches them, so the colorscheme gets the Rex theme's exact colors with termguicolors on.
local M = {}

M.path = vim.fn.stdpath("state") .. "/rex-palette.json"

-- Kanagawa Wave as generated by Rex, used until the terminal has reported its colors once.
M.fallback = {
  fg = "#dcd7ba",
  bg = "#1f1f28",
  [0] = "#090618",
  [1] = "#c34043",
  [2] = "#76946a",
  [3] = "#c0a36e",
  [4] = "#7e9cd8",
  [5] = "#957fb8",
  [6] = "#6a9589",
  [7] = "#c8c093",
  [8] = "#727169",
  [9] = "#e82424",
  [10] = "#98bb6c",
  [11] = "#e6c384",
  [12] = "#7fb4ca",
  [13] = "#938aa9",
  [14] = "#7aa89f",
  [15] = "#dcd7ba",
  [16] = "#1f1f28",
  [17] = "#313547",
  [18] = "#434d69",
  [28] = "#404a42",
  [52] = "#40272d",
  [105] = "#919db9",
  [205] = "#b77a8c",
  [214] = "#c47f5c",
  [232] = "#25252d",
  [233] = "#2c2b32",
  [235] = "#39383d",
  [236] = "#403f42",
  [237] = "#474648",
  [238] = "#4e4c4d",
}

-- Cached palette keyed by slot number plus "fg"/"bg"; the fallback when the cache is missing or
-- unreadable.
function M.load()
  local ok, palette = pcall(function()
    local palette = {}
    for key, color in pairs(vim.json.decode(table.concat(vim.fn.readfile(M.path)))) do
      palette[tonumber(key) or key] = color
    end
    return palette
  end)
  return ok and palette.bg and palette or M.fallback
end

-- Writes to a temporary file and renames it, so another Neovim never reads half-written JSON.
function M.save(palette)
  local cache = {}
  for key, color in pairs(palette) do
    cache[tostring(key)] = color
  end
  vim.fn.mkdir(vim.fn.fnamemodify(M.path, ":h"), "p")
  local tmp = M.path .. "." .. vim.fn.getpid()
  vim.fn.writefile({ vim.json.encode(cache) }, tmp)
  assert(vim.uv.fs_rename(tmp, M.path))
end

-- Asks the terminal for fg, bg and `slots`, then calls on_done(palette). The query ends with DA1,
-- which every terminal answers, in order, so its reply means all others have arrived. A DA1 reply
-- that comes before every slot has answered belongs to another program (Neovim sends DA1 too) and
-- is skipped. Rex answers OSC 4 even for a session the app is not showing, so only fg and bg can
-- be missing. There is no timeout: replies carry no query ID, so a query that ended early would
-- let its late replies fill the next one.
function M.query(slots, on_done)
  local palette = {}
  local group = vim.api.nvim_create_augroup("RexPalette", { clear = true })

  vim.api.nvim_create_autocmd("TermResponse", {
    group = group,
    callback = function(ev)
      local seq = ev.data.sequence
      if seq:match("^\027%[%?[%d;]*c$") then
        local answered = vim.iter(slots):all(function(slot)
          return palette[slot] ~= nil
        end)
        if answered then
          vim.api.nvim_del_augroup_by_id(group)
          -- Leave the TermResponse autocmd first: autocmds do not nest there, so applying the
          -- colorscheme inside it would not fire ColorScheme for other plugins.
          vim.schedule(function()
            on_done(palette)
          end)
        end
        return
      end
      local slot, r, g, b = seq:match("^\027%]4;(%d+);rgb:(%x%x)%x*/(%x%x)%x*/(%x%x)")
      if slot then
        palette[tonumber(slot)] = "#" .. r .. g .. b
        return
      end
      local code
      code, r, g, b = seq:match("^\027%](1[01]);rgb:(%x%x)%x*/(%x%x)%x*/(%x%x)")
      if code then
        palette[code == "10" and "fg" or "bg"] = "#" .. r .. g .. b
      end
    end,
  })

  local queries = { "\027]10;?\027\\", "\027]11;?\027\\" }
  for _, slot in ipairs(slots) do
    queries[#queries + 1] = ("\027]4;%d;?\027\\"):format(slot)
  end
  queries[#queries + 1] = "\027[c"
  vim.api.nvim_ui_send(table.concat(queries))
end

return M
